def orcamento(janela, instrucoes, historico, documentos, saida_max):
    usado = instrucoes + historico + documentos
    livre = janela - usado
    return {"entrada": usado, "livre": livre, "cabe_saida": livre >= saida_max,
            "saida_possivel": max(0, min(livre, saida_max))}

print(orcamento(8192, 300, 2500, 4000, 1000))
